WITH filtered AS (SELECT *, CASE WHEN quantity >= 246 THEN 'High' WHEN quantity >= 113 THEN 'Medium' ELSE 'Low' END AS quantity_level, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM inventory WHERE last_restock > DATE '2023-02-24' AND product_id IN (6, 8)) SELECT id, product_id, quantity_level, days_since_last_restock, COUNT(days_since_last_restock) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_days_since_last_restock, AVG(days_since_last_restock) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_days_since_last_restock, MAX(days_since_last_restock) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_days_since_last_restock FROM filtered;
